head.script:
/************************************************************************************
 * ID           :	ULDSTF09312
 * File         :	ULDSTF09312.xml
 * Name         :	상장폐지
 * Author       :	배성우
 * Description  :	상장형 수익증권
 * Create Date  :	2026-09-07
************************************************************************************/

scwin.vScrenID = "ULDSTF09312.xml";
scwin.vScrenTpCD = "";
scwin.vBzProcsNo = "";
scwin.vIsurCd = "";
scwin.trsIdx;
scwin.rowPos;
//let VListBzTpCd = LIST_BZ_TP_CD_812;//PF
scwin.fr_MktId = $c.session.getUserInfo("market")
// scwin.fr_SecuGrpId = $c.lc.getSecuGrpId($c.stf.InfoMenuID()); //AS-IS
scwin.fr_SecuGrpId = $c.lc.getGlbValue("SECUGRP_ID_PF"); //상장형 수익증권 - 이걸로 변경?
scwin.vListStatCd = "Y";
scwin.RSNCD_DELIST = "4"; //상장폐지사유

scwin.BTN_MAP = {
    "save": "btn_save",       // [저장]
    "modify": "btn_update",      // [수정]
    "delete": "btn_delete",     // [삭제]
    "guide": "btn_dscl",   // [안내문]
};

scwin.onpageload = function () {
    scwin.init();
};

scwin.onpageunload = function () {
};

/* 
 * 화면 초기화
 */
scwin.init = function () {
    $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
    $c.win.setEnterKeyEvent(tbl_search, scwin.btn_search_onclick);
};

/* 
 * 액면가, 상장증권수 조회 하는 API
 */
scwin.fn_isubook_read_sync = async function () {
    dma_selectReq.set("isuCd", ibx_isuCd.getValue());
    const sbmOptions = {
        id: "sbm_selectTotStkCnt",
        action: "/api/listing/lstproc/pf/delisting/select-tot-stk-cnt",
        method: "get",
        ref: "dma_selectReq",
        target: "dma_selectOneRes=body",
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res.responseJSON.success) {

    }
};

/* 
 * 목록 조회
 */
scwin.fn_list_sync = async function () {
    dma_selectReq.set("isuCd", ibx_isuCd.getValue());
    const sbmOptions = {
        id: "sbm_selectList",
        action: "/api/listing/lstproc/pf/delisting/select-list",
        method: "get",
        ref: "dma_selectReq",
        target: "dlt_selectListRes=body",
        gridview: grd_list,
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res.responseJSON.success) {
        tbx_totCnt.setValue(dlt_selectListRes.getRowCount());
        if (scwin.vBzProcsNo === "") {
            $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
        }
    }
};

/* 
 * 상세 조회
 */
scwin.fn_read_sync = async function (row) {
    scwin.vBzProcsNo = dlt_selectListRes.getCellData(row, "bzProcsNo");
    dma_selectOneReq.set("bzProcsNo", scwin.vBzProcsNo);
    const sbmOptions = {
        id: "sbm_selectOne",
        action: "/api/listing/lstproc/pf/delisting/select-one",
        method: "get",
        ref: "dma_selectOneReq",
        target: "dma_selectOneRes=body",
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res.responseJSON.success) {
        if (scwin.vBzProcsNo === "") {
            $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
        } else {
            $c.stf.setButtonSetWithDate(cal_delistDd, false);
            // $c.stf.setButtonSetWithDate2(dma_selectOneRes.get("DSC_YN")); //DSC_YN 없음
        }
        if (scwin.vListStatCd === "D") {
            $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);
        }

    }
};

/* 
 * data 초기화
 */
scwin.fn_initItem = function () {
    $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
    dma_selectOneRes.setEmptyValue();
    scwin.vBzProcsNo = "";
};

/* 
 * 유효성 검증
 */
scwin.fn_CheckForm = async function () {
    let fields = {
        ibx_isuCd: { required: true, name: "종목코드" },
        cal_delistDd: { required: true, name: "상장폐지일" },
    };
    const options = {
        validateType: "alert",
        checkType: "single",
        focus: true,
        fields: fields,
    };
    if (!await $c.validate.validateDataCollect(grp_table, options)) {
        return false;
    }

    if ($c.date.getServerDateTime() >= cal_delistDd.getValue()) {
        $c.win.alert("[상장폐지일]을 현재일이후로 입력하세요.");
        cal_delistDd.focus();
        return false;
    }

    if (scwin.fr_MktId === '2') {
        fields["ibx_delistRsnDsc"] = { required: true, name: "상장폐지사유" };
        if (!await $c.validate.validateDataCollect(grp_table, options)) {
            return false;
        }

        dma_selectOneRes.set("delistRsnDsc", ibx_delistRsnDsc.getValue());
    } else if (scwin.fr_MktId === '1') {
        if (dma_selectOneRes.get("delistRsnCd") === "") {
            $c.win.alert("[상장폐지사유]를 선택하세요.");
            ibx_delistRsnDsc.focus();
            return false;
        }
    }

    fields["ibx_grndRegulNm"] = { required: true, maxLength: 200, name: "근거규정" };
    if (!await $c.validate.validateDataCollect(grp_table, options)) {
        return false;
    }

    return true;
};

/* 
 * 저장
 */
scwin.fn_save = async function () {
    scwin.trsIdx = $c.lc.getGlbValue("TRS_IDX_INSERT");
    if (!await scwin.fn_CheckForm()) return;
    if (!await $c.lc.isProcess('I')) return;
    scwin.vBzProcsNo = await $c.stf.getNewBzProcNo();
    if (String(scwin.vBzProcsNo).length != 14) {
        $c.win.alert($c.data.getMessage("com_complete_0151", "업무처리번호생성"));
    } else {
        dma_selectOneRes.set("bzProcsNo", scwin.vBzProcsNo);
        await scwin.fn_trs();
    }
};

/* 
 * 수정
 */
scwin.fn_update = async function () {
    scwin.trsIdx = $c.lc.getGlbValue("TRS_IDX_UPDATE");
    if (!await scwin.fn_CheckForm()) return;
    if (!await $c.lc.isProcess('U')) return;
    await scwin.fn_trs();
};

/* 
 * 삭제
 */
scwin.fn_delete = async function () {
    if (!await $c.lc.checkDeleteDiscls(dma_BZ_CHECK, scwin.vBzProcsNo)) return;
    if (!await $c.lc.isProcess('D')) return;
    $c.util.setButtonState("grpBtnBox", "delete", scwin.BTN_MAP);
    scwin.trsIdx = $c.lc.getGlbValue("TRS_IDX_DELETE");
    await scwin.fn_trs();
};

/* 
 * 저장/수정/삭제 전송
 */
scwin.fn_trs = async function () {
    let url = "";
    let alertText = "";

    dma_selectOneRes.set("isuCd", ibx_isuCd.getValue());
    dma_selectOneRes.set("isurCd", scwin.vIsurCd);
    dma_selectOneRes.set("mktactApplObjTpCd", "1");

    if (scwin.trsIdx === '1') {
        alertText = "저장";
        url = "/api/listing/lstproc/pf/delisting/register";
    } else if (scwin.trsIdx === '2') {
        alertText = "수정";
        url = "/api/listing/lstproc/pf/delisting/modify";
    } else if (scwin.trsIdx === '3') {
        alertText = "삭제";
        url = "/api/listing/lstproc/pf/delisting/remove";
    }

    const sbmOptions = {
        id: "sbm_save",
        action: url,
        method: "post",
        ref: "dma_selectOneRes",
        // target: "dma_selectOneRes=body",
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res.responseJSON.success) {
        $c.win.alert($c.data.getMessage("com_complete_0150", alertText));
        await scwin.fn_initItem();
        await scwin.fn_list_sync();
        if (scwin.trsIdx != "3") {
            $c.util.setButtonState("grpBtnBox", "update", scwin.BTN_MAP);
            grd_list.setFocusedCell(dlt_selectListRes.getTotalRow() - 1, 0);
            await scwin.fn_read_sync(dlt_selectListRes.getTotalRow() - 1);
        }
    }
};

/* 
 * 공시 안내문작성
 */
scwin.fn_dscl = async function () {
    //TODO
    $c.win.alert("공시 편집기 예정");
    // let OldGet = fn_GetPar;
    // let OldSet = fn_SetPar;
    // fn_GetPar = function(arr, param_dts_isu, param_dma_selectOneRes, param_dts2, param_dts3) {
    //     arr[0] = "68051C"; //PF

    //     arr[1] = scwin.vBzProcsNo;
    //     arr[2] = scwin.vIsurCd;
    //     arr[3] = '1';
    //     arr[4] = "";
    //     arr[5] = '';
    //     $c.stf.CopyDataSet(dma_selectOneRes, param_dma_selectOneRes);
    //     return arr.length;
    // };
    // fn_SetPar = function(arr) {

    // };
    // let wth = 730 + 5;
    // let hgt = 785 + 30;
    // let pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    // await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    // fn_GetPar = OldGet;
    // fn_SetPar = OldSet;
};

/* 
 * 조회 버튼
 */
scwin.btn_search_onclick = async function () {
    if (ibx_isuCd.getValue() === "") {
        await $c.win.alert($c.data.getMessage("com_req_select", "종목"));
        ibx_isuCd.focus();
        return;
    } else {
        scwin.fn_initItem();
        await scwin.fn_isubook_read_sync();
        await scwin.fn_list_sync();
    }
};

/* 
 * 종목코드 검색팝업 버튼
 */
scwin.btn_isuNm_onclick = async function () {
    const data = {
        secugrpId: scwin.fr_SecuGrpId,
    };
    const res = await $c.lc.popFindIsuAll(data);

    ibx_isuCd.setValue(res.isuCd);
    ibx_isuNm.setValue(res.isuKorNm);
    scwin.vIsurCd = res.isurCd;
    await scwin.fn_initItem();
    await scwin.fn_isubook_read_sync();
    await scwin.fn_list_sync();
    scwin.vListStatCd = res.listStatCd;
    if (scwin.vListStatCd === "D") {
        $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);
    }
};

/* 
 * 상장폐지사유 버튼
 */
scwin.btn_delistRsnDsc_onclick = async function () {
    const data = {
        mkt: "1",
        rsn: "05",
    };
    const res = await $c.lc.popFindClssLstRsnCd(scwin.RSNCD_DELIST, data);
    ibx_delistRsnDsc.setValue(res.name);
    ibx_grndRegulNm.setValue(res.regl);
};

scwin.trs_Save_OnSuccess = function () {
    $c.lc.fn_alertMsg('S');
    scwin.fn_initItem();
    scwin.fn_list_sync();
    if (buttonSet.status != "D") {
        scwin.fn_read_sync(dts_List.getTotalRow());
    }
};
scwin.trs_Save_OnFail = function () {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};

scwin.dts_BZ_CHECK_OnLoadError = function () {
    $c.stf.alert_error(dts_BZ_CHECK);
};

/* 
 * 안내문작성 버튼
 */
scwin.btn_dscl_onclick = function (e) {
    scwin.fn_dscl();
};

/* 
 * 삭제 버튼
 */
scwin.btn_delete_onclick = function (e) {
    scwin.fn_delete();
};

/* 
 * 수정 버튼
 */
scwin.btn_update_onclick = function (e) {
    scwin.fn_update();
};

/* 
 * 저장 버튼
 */
scwin.btn_save_onclick = function (e) {
    scwin.fn_save();
};

/* 
 * 목록 클릭
 */
scwin.grd_list_oncellclick = async function (rowIndex, columnIndex, columnId) {
    $c.util.setButtonState("grpBtnBox", "update", scwin.BTN_MAP);
    await scwin.fn_read_sync(rowIndex);
};
